-- La cuenta de seguridad se identifica por un usuario alfanumérico; el correo
-- pasa a ser un medio de contacto de la persona y deja de ser credencial.
ALTER TABLE seguridad.usuarios ADD COLUMN usuario VARCHAR(20);

WITH numerados AS (
  SELECT id_usuarios, ROW_NUMBER() OVER (ORDER BY created_at, id_usuarios) AS numero
  FROM seguridad.usuarios
)
UPDATE seguridad.usuarios AS u
SET usuario = 'USR' || LPAD(n.numero::text, 6, '0')
FROM numerados AS n
WHERE n.id_usuarios = u.id_usuarios;

UPDATE seguridad.usuarios AS u
SET usuario = 'JRUIZT'
WHERE EXISTS (
  SELECT 1
  FROM seguridad.usuarios_roles ur
  JOIN seguridad.roles r ON r.id_roles = ur.fid_roles
  WHERE ur.fid_usuarios = u.id_usuarios
    AND ur.estado = 1
    AND r.codigo = 'SUPERADMIN'
    AND r.estado = 1
);

ALTER TABLE seguridad.usuarios ALTER COLUMN usuario SET NOT NULL;
ALTER TABLE seguridad.usuarios
  ADD CONSTRAINT usuarios_usuario_formato_check
  CHECK (usuario ~ '^[A-Za-z0-9]{1,20}$');
CREATE UNIQUE INDEX usuarios_fid_organizaciones_usuario_key
  ON seguridad.usuarios(fid_organizaciones, usuario);

CREATE TABLE configuracion.departamentos (
  id_departamentos UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  codigo_ubigeo CHAR(2) NOT NULL UNIQUE,
  nombre VARCHAR(80) NOT NULL,
  estado INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by TEXT,
  updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by TEXT
);

CREATE TABLE configuracion.provincias (
  id_provincias UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  fid_departamentos UUID NOT NULL REFERENCES configuracion.departamentos(id_departamentos) ON DELETE RESTRICT,
  codigo_ubigeo CHAR(4) NOT NULL UNIQUE,
  nombre VARCHAR(80) NOT NULL,
  estado INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by TEXT,
  updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by TEXT
);
CREATE INDEX provincias_fid_departamentos_idx ON configuracion.provincias(fid_departamentos);

CREATE TABLE configuracion.distritos (
  id_distritos UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  fid_provincias UUID NOT NULL REFERENCES configuracion.provincias(id_provincias) ON DELETE RESTRICT,
  ubigeo CHAR(6) NOT NULL UNIQUE,
  nombre VARCHAR(100) NOT NULL,
  estado INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by TEXT,
  updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by TEXT
);
CREATE INDEX distritos_fid_provincias_idx ON configuracion.distritos(fid_provincias);

CREATE TABLE personas.personas_correos (
  id_personas_correos UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  fid_personas UUID NOT NULL REFERENCES personas.personas(id_personas) ON DELETE CASCADE,
  correo VARCHAR(254) NOT NULL,
  es_notificacion BOOLEAN NOT NULL DEFAULT false,
  verificado_en TIMESTAMPTZ(3),
  estado INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by TEXT,
  updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by TEXT,
  CONSTRAINT personas_correos_normalizado_check CHECK (correo = LOWER(BTRIM(correo))),
  CONSTRAINT personas_correos_fid_personas_correo_key UNIQUE (fid_personas, correo)
);
CREATE INDEX personas_correos_fid_personas_es_notificacion_idx
  ON personas.personas_correos(fid_personas, es_notificacion);
CREATE UNIQUE INDEX personas_correos_notificacion_unica_idx
  ON personas.personas_correos(fid_personas)
  WHERE es_notificacion AND estado = 1;

SELECT u.fid_personas, LOWER(BTRIM(u.correo)), true, u.correo_verificado_en,
       u.id_usuarios::text, u.id_usuarios::text
FROM seguridad.usuarios u
ON CONFLICT (fid_personas, correo) DO UPDATE
SET es_notificacion = true,
    verificado_en = COALESCE(personas.personas_correos.verificado_en, EXCLUDED.verificado_en);

SELECT p.id_personas, LOWER(BTRIM(p.correo)), false, p.created_by, p.updated_by
FROM personas.personas p
WHERE p.correo IS NOT NULL AND BTRIM(p.correo) <> ''
ON CONFLICT (fid_personas, correo) DO NOTHING;

ALTER TABLE personas.personas
  ADD COLUMN fid_paises UUID REFERENCES system.paises(id_paises) ON DELETE RESTRICT,
  ADD COLUMN fid_distritos UUID REFERENCES configuracion.distritos(id_distritos) ON DELETE RESTRICT,
  ADD COLUMN codigo_estado_civil TEXT,
  ADD COLUMN codigo_nivel_instruccion TEXT,
  ADD COLUMN ciudad VARCHAR(100),
  ADD COLUMN lugar_nacimiento VARCHAR(150),
  ADD COLUMN direccion VARCHAR(200),
  ADD COLUMN referencia VARCHAR(200),
  ADD COLUMN telefono_principal VARCHAR(30),
  ADD COLUMN telefono_emergencia VARCHAR(30);

UPDATE personas.personas SET telefono_principal = telefono WHERE telefono IS NOT NULL;
CREATE INDEX personas_fid_paises_idx ON personas.personas(fid_paises);
CREATE INDEX personas_fid_distritos_idx ON personas.personas(fid_distritos);

ALTER TABLE seguridad.usuarios DROP CONSTRAINT IF EXISTS usuarios_fid_organizaciones_correo_key;
DROP INDEX IF EXISTS seguridad.usuarios_fid_organizaciones_correo_key;
ALTER TABLE seguridad.usuarios DROP COLUMN correo_verificado_en, DROP COLUMN correo;
ALTER TABLE personas.personas DROP COLUMN telefono, DROP COLUMN correo;

-- Catálogos administrativos oficiales INEI (actualización publicada 2025-09-17).
ON CONFLICT (codigo_ubigeo) DO UPDATE SET nombre = EXCLUDED.nombre, estado = 1;

ON CONFLICT (codigo_ubigeo) DO UPDATE SET nombre = EXCLUDED.nombre, estado = 1;

ON CONFLICT (ubigeo) DO UPDATE SET nombre = EXCLUDED.nombre, estado = 1;

ON CONFLICT (codigo_grupo, codigo) DO UPDATE
SET etiqueta = EXCLUDED.etiqueta, orden = EXCLUDED.orden, estado = 1;

CREATE TRIGGER establecer_updated_at BEFORE UPDATE ON configuracion.departamentos
  FOR EACH ROW EXECUTE FUNCTION configuracion.establecer_updated_at();
CREATE TRIGGER establecer_updated_at BEFORE UPDATE ON configuracion.provincias
  FOR EACH ROW EXECUTE FUNCTION configuracion.establecer_updated_at();
CREATE TRIGGER establecer_updated_at BEFORE UPDATE ON configuracion.distritos
  FOR EACH ROW EXECUTE FUNCTION configuracion.establecer_updated_at();
CREATE TRIGGER establecer_updated_at BEFORE UPDATE ON personas.personas_correos
  FOR EACH ROW EXECUTE FUNCTION configuracion.establecer_updated_at();
